import{_ as t,l as r,o as a,c as s,v as o,p as n,x as i,d as c,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const N=JSON.parse('{"title":"网卡驱动与 NAPI","description":"","frontmatter":{"title":"网卡驱动与 NAPI","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/napi.md","filePath":"cs/napi.md","lastUpdated":1789023840000}'),_={name:"cs/napi.md"};function u(h,e,P,A,f,I){const l=r("Mermaid");return a(),s("div",null,[e[1]||(e[1]=o('<h1 id="网卡驱动与-napi" tabindex="-1">网卡驱动与 NAPI <a class="header-anchor" href="#网卡驱动与-napi" aria-label="Permalink to &quot;网卡驱动与 NAPI&quot;">​</a></h1><div class="epigraph"><p>NAPI 在第一包用中断叫醒，随后关中断、在软中断里轮询收包，直到配额用尽或队列空再开中断。</p><footer>—— 据 Salim, Olsson, Kuznetsov, Beyond Softnet；Linux NAPI 文档</footer></div><p><a href="/cs/skbuff">上一课</a>有了包对象。若每帧一个硬中断，万兆上会 livelock：<a href="/cs/io-polling">轮询 I/O</a> 在存储侧已见过同一税。缺口是 <strong>NAPI</strong>：Linux 网卡的混合中断/轮询。本课不把 XDP 提前展开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>livelock：CPU 全在 IRQ 里建 skb，协议层得不到时间。NAPI：驱动注册 <code>napi_struct</code>，IRQ 只 <code>napi_schedule</code>，<code>poll()</code> 从环形缓冲取描述符、填 skb、<code>netif_receive_skb</code>。配额（weight）防止一网卡饿死调度。缺口：多队列网卡每队列一个 NAPI；忙时类似存储 poll，闲时仍靠 IRQ 省电。</p><p><span class="marginnote">busy polling（<code>SO_BUSY_POLL</code>）让用户线程直接调 napi poll，与存储 IOPOLL 同构。本课先钉内核软中断路径。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>开中断 → 来包 → 关该队列 IRQ → 软中断 <code>net_rx_action</code> 调 poll → 上送协议栈 → 若工作仍多则再排 NAPI。对照 NVMe poll：一个是块 CQ，一个是 NIC ring。对照 <a href="/cs/blkio-cgroup">blkio</a>：包的节流在 qdisc/cgroup net，不在 NAPI 配额里。</p>',8)),(a(),n(d,null,{default:i(()=>[p(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20IRQ%5B%22%E7%A1%AC%E4%B8%AD%E6%96%AD%22%5D%20--%3E%20SCH%5B%22napi_schedule%22%5D%0A%20%20SCH%20--%3E%20POLL%5B%22poll%20%E6%94%B6%E7%8E%AF%22%5D%0A%20%20POLL%20--%3E%20SKB%5B%22%E5%BB%BA%20sk_buff%22%5D%0A%20%20SKB%20--%3E%20RX%5B%22netif_receive_skb%22%5D%0A%20%20POLL%20--%3E%7C%22%E7%A9%BA%E9%97%B2%22%7C%20EI%5B%22%E9%87%8D%E6%96%B0%E5%BC%80%E4%B8%AD%E6%96%AD%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>NAPI 把「包到达」从逐帧 IRQ 换成批量，使协议栈与应用能跑。它是 Linux 网络性能的底座，后课 GRO 在 poll 里聚合。不要写成实时保证：软中断仍抢占用户，过重会 raise <code>ksoftirqd</code>。</p><p>与设备模型：网卡仍是 PCI 设备，本课只管收包引擎。</p><p>实现上：weight 用尽会让出 softirq，避免一网卡饿死调度。RPS 把包再丢到别的 CPU 的 backlog，等于软件 RSS。busy poll 让套接字在 recv 里直接 napi_poll。 读法上只引用<a href="/cs/skbuff">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>网卡驱动与 NAPI</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 ethtool coalescing 参数。不保证无线驱动的 NAPI 形状相同。下一课在 poll 里把小包粘成大段：GRO，以及发送侧的 GSO。</p><p>版本字段会变，课序钉的是机制对象「网卡驱动与 NAPI」，不是某一主线内核的结构体名。 后课默认：收包走 NAPI 轮询配额。分段卸载与聚合，下一课 GRO/GSO。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>NAPI：首包中断，随后轮询收环，用配额限时。</li><li>多队列对应多个 napi_struct。</li><li>GRO/GSO 是下一课。</li><li>出处：Salim et al.；Linux NAPI；Benvenuti <em>ULNI</em>。</li></ul>',11))])}const S=t(_,[["render",u]]);export{N as __pageData,S as default};
